import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/15/","title":"第 15 课 · 虚拟语气 Subjunctive Mood | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 15 课 · 虚拟语气 Subjunctive Mood","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/15/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十五课 语法专题 · 第十五课 对应教材上册 P175–P187 · 三大形式：(should) be 型、were 型、if 条件句及主句虚拟，外加 It is (high/about) time 特殊结构。 考点地图 · 点击跳转 (should) ...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 15 课 · 虚拟语气 Subjunctive Mood\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/15/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 15 课 · 虚拟语气 Subjunctive Mood"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十五课 语法专题 · 第十五课 对应教材上册 P175–P187 · 三大形式：(should) be 型、were 型、if 条件句及主句虚拟，外加 It is (high/about) time 特殊结构。 考点地图 · 点击跳转 (should) ..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 15 课 · 虚拟语气 Subjunctive Mood"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/15/"}]]},"readingTime":{"minutes":61.46,"words":18439},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/15.md","headers":[]}`),u={name:`15.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0015-subjunctive-mood.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第十五课`,-1)]),l[10]||=r(`<p>语法专题 · 第十五课</p><p>对应教材上册 P175–P187 · 三大形式：(should) be 型、were 型、if 条件句及主句虚拟，外加 It is (high/about) time 特殊结构。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>(should) be 型虚拟</strong>：&quot;一二四四&quot;标志词、词形变化、主观看法、lest/in case/for fear that、祝愿</a></li><li><a href="#pt-2"><strong>were 型虚拟</strong>：wish、if only、as if/as though、would rather 等</a></li><li><a href="#pt-3"><strong>if 条件句及主句虚拟</strong>：同一时空、错综时间、虚实混用、倒装、含蓄虚拟、情态动词 + have done</a></li><li><a href="#pt-4"><strong>特殊虚拟结构</strong>：It is (high/about) time...</a></li></ol></div><h2 id="什么是虚拟语气" tabindex="-1"><a class="header-anchor" href="#什么是虚拟语气"><span>什么是虚拟语气</span></a></h2><p>英语语气可分为三类：</p><table><thead><tr><th>语气</th><th>作用</th><th>例句</th></tr></thead><tbody><tr><td><strong>陈述语气</strong></td><td>陈述事实或可能发生的事情</td><td>You guys are so smart.（你们真聪明。）</td></tr><tr><td><strong>祈使语气</strong></td><td>表示请求、命令、警告等</td><td>Be careful, please!（请小心！）</td></tr><tr><td><strong>虚拟语气</strong></td><td>表达假设、愿望、建议等不真实或未实现的情况</td><td>If I were you...（如果我是你……）</td></tr></tbody></table><p>虚拟语气用<strong>动词的不同形式</strong>表示不能实现或与事实相反的假设。课件用&quot;想得美&quot;&quot;后悔药&quot;&quot;做梦&quot;帮助理解：例如&quot;如果我是皇上&quot;&quot;真希望华妃失宠&quot;&quot;我建议皇上听我的&quot;。其形式大体分为 <strong>(should) be 型、were 型、if 条件句及主句虚拟</strong>三类。</p><h2 id="第一部分-·-should-be-型虚拟" tabindex="-1"><a class="header-anchor" href="#第一部分-·-should-be-型虚拟"><span>第一部分 · (should) be 型虚拟</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一部分 · (should) be 型虚拟</p><ul><li><strong>目标</strong>：解决“从句里的谓语为什么长得怪”：认出“一二四四”标志词，把从句谓语写成 (should) + 动词原形，并分清 suggest / insist 的词义。</li><li><strong>建议用时</strong>：13 分钟</li><li><strong>知识点</strong>：<code>虚拟语气的实质（与事实相反 / 未实现）</code> <code>(should) be 型虚拟（一二四四标志词）</code> <code>suggest / insist 看词义</code> <code>It is + 形容词/名词 + that (should) do</code> <code>lest / in case / for fear that 与 May 祝愿</code></li></ul></div><h3 id="第一部分-·-should-be-型虚拟-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一部分-·-should-be-型虚拟-·-小步学"><span>第一部分 · (should) be 型虚拟 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>虚拟语气：表达设想、愿望或建议</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>(should) be 型：should 可省，动词永远用原形</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>变形词与 It is necessary that：从句照样虚拟</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>suggest / insist 先看词义，再决定用不用虚拟</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>lest / in case / for fear that 与 May 祝愿</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：背出“一二四四”标志词，再用一句话解释 suggest 什么时候用虚拟、什么时候不用。</p><div class="hint-container tip"><p class="hint-container-title">(should) be 型：should 可省，动词永远用原形</p><p><strong>句意</strong>：We demand that the meeting (should) be postponed. 意思是“我们要求会议延期”。</p><p><strong>拆解</strong></p><ul><li>We demand 是主句，demand 属于“四个要求”之一</li><li>that the meeting (should) be postponed 是宾语从句，从句谓语是 (should) + be + 过去分词</li><li>should 通常可以省略，所以会出现 he be at the factory 这种看起来缺谓语的写法</li><li>meeting 与 postpone 是被动关系，所以用 (should) be postponed，而不是 postpone</li></ul><p><strong>语法</strong>：“一二四四”标志词：一个主张 insist；两个命令 order、command；四个建议 suggest、advise、propose、recommend；四个要求 ask、require、request、demand。这些词后的 that 从句用 (should) + 动词原形，should 可省；被动结构为 (should) be + 过去分词。</p><ol><li>标志词用现在时或过去时，从句谓语形式都不变</li><li>(should) + 动词原形：不随主句时态变化</li></ol><p>正例：We demand that the meeting (should) be postponed.；The job would require that he (should) be at the factory at 7 o&#39;clock.；The government suggests people (should) spend the Spring Festival at their working place. 反例：We demand that the meeting is postponed. ×（从句该用 (should) be postponed）；The government suggests people to spend… ×（suggest 不接“宾语 + 不定式”，要用 that 从句） 适用边界：这条规则只管标志词这一侧的从句；如果主句动词是普通动词（如 I hope that he comes），从句照常用真实时态。</p><p><strong>口诀</strong>：一坚持、二命令、四建议、四要求 —— 先背标志词，再背形式：从句 = (should) + 动词原形，should 可有可无。</p></div><div class="hint-container tip"><p class="hint-container-title">变形词与 It is necessary that：从句照样虚拟</p><p><strong>句意</strong>：It is required that the students (should) learn a foreign language. 意思是“要求学生学习一门外语”。</p><p><strong>拆解</strong></p><ul><li>require 变成被动结构 It is required 之后，从句仍然用 (should) + 动词原形</li><li>The requirement is that…（表语从句）、his proposal that…（同位语从句）同样如此</li><li>Your advice that she (should) wait till next week is reasonable. 里 advice 是 suggest 的名词形式，同位语从句也用 (should) wait</li><li>It is necessary that a worker (should) accomplish his work on time. 里的 necessary 属于“必要性”类形容词</li></ul><p><strong>语法</strong>：标志词变成名词、形容词后（requirement、proposal、advice、necessary、important、essential、vital、advisable、desirable、natural、proper、possible、compulsory 等），引导的主语从句、表语从句、同位语从句同样用 (should) + 动词原形；It is of great importance that… 也一样。</p><p>正例：It is required that the students (should) learn a foreign language.；Your advice that she (should) wait till next week is reasonable.；It is necessary that a worker (should) accomplish his work on time.；The requirement is that all the equipment (should) be checked twice. 反例：It is necessary that a worker accomplishes his work on time. ×（从句要用原形 accomplish）；Your advice that she waits till next week is reasonable. ×（同位语从句该用 (should) wait） 适用边界：先把标志词找准：It is important that… 里 important 是“重要性”类，从句才虚拟；It is important 若只是描述事实（It is important to him.），就没有从句可言。</p><p><strong>口诀</strong>：动词变名词、形容词，从句形式不变 —— 认出 requirement、advice、necessary 都来自那批标志词，从句照样用 (should) + 原形。</p></div><div class="hint-container tip"><p class="hint-container-title">suggest / insist 先看词义，再决定用不用虚拟</p><p><strong>句意</strong>：We all suggest that a lab (should) be built. 意思是“我们都建议建一个实验室”；Her expression suggests that she is angry. 意思是“她的表情表明她生气了”。</p><p><strong>拆解</strong></p><ul><li>第一句 suggest 表“建议”，从句用 (should) be built</li><li>第二句 suggest 表“表明”，从句讲的是客观事实，用陈述语气 is angry</li><li>insist 有同样的两面：She insisted that we should find the source of the river.（坚持要求）/ She insisted that she had done nothing wrong.（坚持说）</li><li>The boy insisted that he was old enough, and (should) be given the right to make his own choice. 一句里两种用法同时出现</li></ul><p><strong>语法</strong>：suggest 表“建议”、insist 表“坚持要求”时，从句用 (should) + 动词原形；suggest 表“暗示、表明、说明”、insist 表“坚持说”时，从句陈述客观事实，用陈述语气。</p><p>正例：We all suggest that a lab (should) be built.；Her expression suggests that she is angry.；She insisted that we should find the source of the river.；She insisted that she had done nothing wrong. 反例：Her expression suggests that she (should) be angry. ×（“表明”义不用虚拟）；She insisted that she (should) have done nothing wrong. ×（“坚持说”义用陈述语气 had done） 适用边界：判断口决：从句内容“还没发生、要被促成” → 虚拟；从句内容“已经存在的事实” → 陈述语气。</p><p><strong>口诀</strong>：建议才虚拟，表明用事实 —— 先翻译一遍从句内容：是“要做的事”就虚拟，是“已经的事”就陈述。</p></div><div class="hint-container tip"><p class="hint-container-title">lest / in case / for fear that 与 May 祝愿</p><p><strong>句意</strong>：He took his raincoat with him in case it (should) rain. 意思是“他带上雨衣，以防下雨”。</p><p><strong>拆解</strong></p><ul><li>in case 表“万一、以防”，从句用 (should) + 动词原形，should 也可省</li><li>for fear that he (should) be caught in the rain：for fear that 表“唯恐”，形式相同</li><li>lest 表“以免”，同样接 (should) + 动词原形</li><li>祝愿句用 May + 主语 + 动词原形：May you be happy.</li></ul><p><strong>语法</strong>：lest、in case、for fear that 表示“以免、担心、万一”时，从句用 (should) + 动词原形；表示祝愿用 May + 主语 + 动词原形。</p><p>正例：He took his raincoat with him in case it (should) rain.；He took his raincoat with him for fear that he (should) be caught in the rain.；May you be happy. 反例：He took his raincoat with him in case it will rain. ×（in case 从句用 (should) + 原形）；May you are happy. ×（May 后接动词原形 be） 适用边界：in case 也可作条件连词表“万一”出现在真实条件句中（In case there is a fire, what should we do first?），此时按陈述语气处理；这里讲的是它作“防备”用法时的虚拟形式。</p><p><strong>口诀</strong>：以防万一用 (should) 原形，祝愿句用 May 加原形 —— 两类结构都要求“原形”，一个是担心，一个是祝福。</p></div><h3 id="_1-一二四四-标志词" tabindex="-1"><a class="header-anchor" href="#_1-一二四四-标志词"><span>1. “一二四四&quot;标志词</span></a></h3><table><thead><tr><th>类别</th><th>标志词</th></tr></thead><tbody><tr><td><strong>一个主张</strong></td><td>insist</td></tr><tr><td><strong>两个命令</strong></td><td>order、command</td></tr><tr><td><strong>四个建议</strong></td><td>suggest、advise、propose、recommend</td></tr><tr><td><strong>四个要求</strong></td><td>ask、require、request、demand</td></tr></tbody></table><p>这些动词引导宾语从句时，从句谓语用：<strong>动词 + (that) + 从句主语 + (should) do / (should) be done</strong>。should 一般可以省略；被动结构为 <strong>(should) be + 过去分词</strong>。</p><p>We demand that the meeting (should) <strong>be postponed</strong>.（我们要求会议延期。）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>一坚持、二命令、四建议、四要求。</strong></p></div><h3 id="_2-变形词引导其他名词性从句" tabindex="-1"><a class="header-anchor" href="#_2-变形词引导其他名词性从句"><span>2. 变形词引导其他名词性从句</span></a></h3><p>上述词变成<strong>名词、形容词</strong>等形式后，引导的主语从句、表语从句或同位语从句同样用 <strong>(should) + 动词原形</strong>。</p><p>It is required that the students (should) <strong>learn</strong> a foreign language.（要求学生学习一门外语。） The requirement is that all the equipment in the meeting room (should) <strong>be checked</strong> twice before.（要求是会议室里的所有设备事先检查两遍。） We didn&#39;t stand for his proposal that the meeting (should) <strong>be postponed</strong>.（我们不支持他提出的会议延期举行的建议。）</p><h3 id="_3-suggest-与-insist-的特例" tabindex="-1"><a class="header-anchor" href="#_3-suggest-与-insist-的特例"><span>3. suggest 与 insist 的特例</span></a></h3><div class="hint-container caution"><p class="hint-container-title">易错</p><p>看词义，不只看词形 <strong>suggest</strong> 表示&quot;<strong>建议</strong>&quot;时用虚拟；表示&quot;<strong>暗示、表明、说明</strong>&quot;时陈述客观事实，不用虚拟。</p><p><strong>insist</strong> 表示&quot;<strong>坚持要求</strong>&quot;时用虚拟；表示&quot;<strong>坚持说</strong>&quot;时陈述事实，不用虚拟。</p></div><p>We all suggest that a lab (should) <strong>be built</strong>.（我们都建议建一个实验室。） Her expression <strong>suggests that she is</strong> angry.（她的表情表明她生气了。） She <strong>insisted that we should find</strong> the source of the river.（她坚持要求我们找到河流的源头。） She <strong>insisted that she had done</strong> nothing wrong.（她坚持说她没有做错任何事。）</p><h3 id="_4-it-is-名词-形容词-that-从句" tabindex="-1"><a class="header-anchor" href="#_4-it-is-名词-形容词-that-从句"><span>4. It is + 名词/形容词 + that 从句</span></a></h3><p>表示必要性、重要性、强制性、合适性、义务性或主观反应时，that 从句用 <strong>(should) + 动词原形</strong>。常见形容词：advisable（可取的）、desirable（可取的）、essential（必要的）、vital（至关重要的）、important（重要的）、necessary（必要的）、unnecessary（不必要的）、proper（适当的）、possible（可能的）、impossible（不可能的）、natural（自然的）、surprising（令人惊讶的）、compulsory（强制的）。</p><p>It is important that students graduating from universities (should) <strong>have</strong> not only theory but also practice.（大学毕业生不仅应掌握理论，还应具备实践能力，这很重要。） It is of great importance that smoking (should) <strong>be banned</strong> in public.（在公共场所应该禁止吸烟，这非常重要。）</p><h3 id="_5-lest-in-case-for-fear-that-与祝愿" tabindex="-1"><a class="header-anchor" href="#_5-lest-in-case-for-fear-that-与祝愿"><span>5. lest / in case / for fear that 与祝愿</span></a></h3><p><strong>lest、in case、for fear that</strong> 表示&quot;恐怕、担心、以免、万一&quot;时，从句用 <strong>(should) + 动词原形</strong>。</p><p>He took his raincoat with him <strong>in case it (should) rain</strong>.（他带上雨衣，以防下雨。） He took his raincoat with him <strong>for fear that he (should) be caught</strong> in the rain.（他带上雨衣，唯恐淋雨。）</p><p>表示祝愿可用：<strong>May + 主语 + 动词原形</strong>。</p><p><strong>May you be happy.</strong>（愿你幸福。）</p><h2 id="第二部分-·-were-型虚拟" tabindex="-1"><a class="header-anchor" href="#第二部分-·-were-型虚拟"><span>第二部分 · were 型虚拟</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二部分 · were 型虚拟</p><ul><li><strong>目标</strong>：解决“愿望句里的过去式到底指什么时候”：把 wish、if only、as if、would rather 后的时态按“现在退过去、过去退完成、将来用 would”对准。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>wish / if only 的 were 型虚拟</code> <code>as if / as though 虚拟</code> <code>would rather 等 + 从句虚拟</code> <code>错综时间虚拟与虚实混用</code></li></ul></div><h3 id="第二部分-·-were-型虚拟-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二部分-·-were-型虚拟-·-小步学"><span>第二部分 · were 型虚拟 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>虚拟语气：表达设想、愿望或建议</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>wish 后的时态要“往回退一格”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>if only 与 only if：词序一变，意思全变</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>as if / as though：与事实相反就用虚拟</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>would rather 后的过去式，不是在讲过去</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用“退一格”的说法讲清 wish / if only / as if / would rather 四处从句的时态选择。</p><div class="hint-container tip"><p class="hint-container-title">wish 后的时态要“往回退一格”</p><p><strong>句意</strong>：I wish I were a bird. 意思是“我希望自己是一只鸟”（事实上我不是鸟）。</p><p><strong>拆解</strong></p><ul><li>与现在事实相反：从句用一般过去时，be 一律 were（I wish I were a bird.）</li><li>与过去事实相反：从句用过去完成时 had done（I wish that I had passed the final exam. 实际没通过）</li><li>与将来事实相反：从句用 would/could + do（I wish he would come to help me with my paper.）</li></ul><p><strong>语法</strong>：wish 后接宾语从句用虚拟语气：与现在相反用一般过去时（be 用 were），与过去相反用过去完成时，与将来相反用 would/could + 动词原形。</p><ol><li>愿望指向现在 → 从句退回一般过去式（be 一律 were）</li><li>回看过去 → 从句退回过去完成时 had done</li><li>看向将来 → 从句用 would/could + do</li></ol><p>正例：I wish I were a bird.；I wish that I had passed the final exam.；I wish he would/could come to help me with my paper. 反例：I wish I am a bird. ×（与现在相反要用过去式，be 用 were）；I wish I have read the book. ×（与过去相反要用 had read） 适用边界：wish 从句里的过去式不代表事情发生在过去，它只表示“与事实有距离”；判断时间要靠句中的时间词（now / last year / next week）。</p><p><strong>口诀</strong>：现在过去式，过去 had done，将来 would do —— 把 wish 想成“后退一步”：想现在，句子退到过去；想过去，句子退到过去完成。</p></div><div class="hint-container tip"><p class="hint-container-title">if only 与 only if：词序一变，意思全变</p><p><strong>句意</strong>：If only she were here at this moment. 意思是“要是她此刻在这里就好了”；Only if the government takes some measures will this problem be solved. 意思是“只有政府采取一些措施，这个问题才能得到解决”。</p><p><strong>拆解</strong></p><ul><li>if only 表“要是……就好了”，引出感叹式的愿望，从句用虚拟（与现在相反用 were）</li><li>only if 表“只有……才”，是条件；位于句首时主句部分倒装：will this problem be solved</li><li>If only I hadn&#39;t made this mistake. 与过去相反，用过去完成时</li><li>If only he had lain quietly as the doctor instructed, he would not suffer so much now. 里从句指过去、主句指现在</li></ul><p><strong>语法</strong>：if only 表示“要是……就好了”，从句用虚拟语气（现在相反用过去式、过去相反用 had done、将来相反用 would/could do）；only if 表示“只有……才”，位于句首时主句部分倒装。</p><ol><li>If only 从句指过去：had done（当时并没有照做）</li><li>主句结果落在现在：would not suffer now</li><li>两半时间不同 → 错综时间虚拟</li></ol><p>正例：If only she were here at this moment.；If only I hadn&#39;t made this mistake.；Only if the government takes some measures will this problem be solved. 反例：If only she is here at this moment. ×（与现在相反要用 were）；Only if the government takes some measures this problem will be solved. ×（only if 置首时主句要部分倒装） 适用边界：两个词组词序相反、功能相反：if only 是感叹愿望，only if 是条件。做题先看词序，再决定用不用虚拟、要不要倒装。</p><p><strong>口诀</strong>：if only 是愿望，only if 是条件 —— 愿望句配虚拟，条件句配倒装，两者别串门。</p></div><div class="hint-container tip"><p class="hint-container-title">as if / as though：与事实相反就用虚拟</p><p><strong>句意</strong>：He talked about the film as if he had seen it before. 意思是“他谈起那部电影，好像以前看过似的”。</p><p><strong>拆解</strong></p><ul><li>主句 talked 是过去，从句的“看过”发生在更早，所以用 had seen</li><li>It seems as if the meeting would never end. 用 would 表与事实相反的未来</li><li>The sun rises in the east and sets in the west, so it seems as if the sun were circling round the earth. 与现在事实相反，be 用 were</li><li>若所述可能是事实，也可以不用虚拟：It looks as if the weather may pick up very soon.</li></ul><p><strong>语法</strong>：as if/as though 引导方式状语从句，所述情况与事实相反或极不可能发生时用虚拟语气：与现在相反用一般过去时（be 用 were），与过去相反用过去完成时，与将来相反用 would/could/might + 动词原形。</p><ol><li>主句 talked：过去</li><li>从句 had seen：更早发生，用过去完成时</li></ol><p>正例：He talked about the film as if he had seen it before.；It seems as if the meeting would/could/might never end.；The two students talked as if they had been friends for years. 反例：He talked about the film as if he saw it before. ×（“看过”在谈话之前，要用 had seen）；The two students talked as if they are friends for years. ×（与事实相反要用虚拟） 适用边界：as if 后面不一定要虚拟：所述可能是事实时用陈述语气（It looks as if the weather may pick up very soon.）。先判断真假，再选语气。</p><p><strong>口诀</strong>：与事实相反才虚拟，先判真假再定时态 —— as if 是“仿佛”，既然是“仿佛”，多数情况与事实有距离，但也要留一条陈述语气的路。</p></div><div class="hint-container tip"><p class="hint-container-title">would rather 后的过去式，不是在讲过去</p><p><strong>句意</strong>：I would rather you came here now. 意思是“我宁愿你现在来这里”。</p><p><strong>拆解</strong></p><ul><li>从句 came 是过去式，但句子里有 now —— 过去式只表示“与事实有距离”</li><li>对过去的愿望用过去完成时：I would rather he hadn&#39;t told me the truth.</li><li>would rather 后面接不带 to 的不定式时是另一种结构：I would rather stay at home.</li></ul><p><strong>语法</strong>：would rather、would sooner、would prefer、had rather 后的从句：用一般过去时表示现在或将来的愿望，用过去完成时表示对过去的愿望。</p><ol><li>愿望指向现在或将来 → 从句用一般过去时</li><li>愿望指向过去 → 从句用过去完成时</li></ol><p>正例：I would rather you came here now.；I would rather he hadn&#39;t told me the truth.；I&#39;d rather he came the day after tomorrow. 反例：I would rather you come here now. ×（从句要用过去式 came）；I would rather he didn&#39;t tell me the truth yesterday. ×（对过去的愿望要用过去完成时） 适用边界：would rather 自己接动词时用原形（would rather stay），接从句时才用过去式/过去完成时；两种结构不要混在一起写。</p><p><strong>口诀</strong>：现在用过去，过去用完成 —— 从句里的时态比真实时间“退一步”，这是 were 型虚拟共同的记号。</p></div><p>were 型虚拟表达与事实相反、未曾实现的主观愿望：</p><table><thead><tr><th>愿望与事实的关系</th><th>从句谓语形式</th></tr></thead><tbody><tr><td>与现在事实相反</td><td>一般过去时；be 一律用 <strong>were</strong></td></tr><tr><td>与过去事实相反</td><td>过去完成时 <strong>had done</strong></td></tr><tr><td>与将来事实相反</td><td>过去将来时 <strong>would/could + do</strong></td></tr></tbody></table><h3 id="_1-wish-引导宾语从句" tabindex="-1"><a class="header-anchor" href="#_1-wish-引导宾语从句"><span>1. wish 引导宾语从句</span></a></h3><p>I wish I <strong>were</strong> a bird.（我希望自己是一只鸟。——与现在事实相反） I wish that I <strong>had passed</strong> the final exam.（我真希望自己已经通过了期末考试。——与过去事实相反，实际未通过） I wish he <strong>would/could come</strong> to help me with my paper, but he will go on business next week.（我希望他能来帮我写论文，但他下周要出差。——与将来事实相反）</p><h3 id="_2-if-only-感叹句" tabindex="-1"><a class="header-anchor" href="#_2-if-only-感叹句"><span>2. if only 感叹句</span></a></h3><p>if only 表示&quot;要是……就好了&quot;。</p><p>If only she <strong>were</strong> here at this moment.（要是她此刻在这里就好了。——与现在事实相反） If only I <strong>hadn&#39;t made</strong> this mistake.（要是我没有犯这个错误就好了。——与过去事实相反） If only you <strong>would/could attend</strong> my wedding.（要是你能参加我的婚礼就好了。——与将来事实相反）</p><div class="hint-container caution"><p class="hint-container-title">易错</p><p>易错：if only 与 only if<strong>if only</strong> = 要是……就好了；<strong>only if</strong> = 只有……才。<strong>Only if 位于句首时，主句采用部分倒装</strong>：<strong>Only if</strong> the government takes some measures <strong>will this problem be solved</strong>.（只有政府采取一些措施，这个问题才能得到解决。）</p></div><h3 id="_3-as-if-as-though" tabindex="-1"><a class="header-anchor" href="#_3-as-if-as-though"><span>3. as if / as though</span></a></h3><p>as if / as though 引导状语从句，表示&quot;似乎、好像&quot;，所述情况与事实相反或极不可能发生。</p><p>He talked about the film <strong>as if he had seen</strong> it before.（他谈起那部电影，好像以前看过似的。） It seems <strong>as if the meeting would/could/might never end</strong>.（会议似乎怎么也不会结束。）</p><h3 id="_4-would-rather-等引导宾语从句" tabindex="-1"><a class="header-anchor" href="#_4-would-rather-等引导宾语从句"><span>4. would rather 等引导宾语从句</span></a></h3><p><strong>would rather、would sooner、would prefer、had rather</strong> 表示&quot;宁愿、但愿&quot;。从句用<strong>一般过去时</strong>表示现在或将来的愿望，用<strong>过去完成时</strong>表示对过去的愿望。</p><p>I would rather you <strong>came</strong> here now.（我宁愿你现在来这里。——现在的愿望） I would rather he <strong>hadn&#39;t told</strong> me the truth.（我宁愿他当时没有告诉我真相。——对过去的愿望）</p><h2 id="第三部分-·-if-条件句虚拟及主句虚拟" tabindex="-1"><a class="header-anchor" href="#第三部分-·-if-条件句虚拟及主句虚拟"><span>第三部分 · if 条件句虚拟及主句虚拟</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第三部分 · if 条件句虚拟及主句虚拟</p><ul><li><strong>目标</strong>：解决“条件句填哪一格”：先定时间（现在、过去、将来、错综），再配从句与主句两半形式，并处理含蓄条件与情态动词 + have done。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>if 条件句与主句虚拟（三种时空）</code> <code>错综时间虚拟与虚实混用</code> <code>省略 if 的倒装（were / should / had 提前）</code> <code>含蓄虚拟（without / but for / otherwise / or）</code> <code>情态动词 + have done（本应做而未做）</code></li></ul></div><h3 id="第三部分-·-if-条件句虚拟及主句虚拟-·-小步学" tabindex="-1"><a class="header-anchor" href="#第三部分-·-if-条件句虚拟及主句虚拟-·-小步学"><span>第三部分 · if 条件句虚拟及主句虚拟 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>虚拟语气：表达设想、愿望或建议</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>同一时空：现、过、将来三行表</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>错综时间：各看各的时间标志</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>省略 if 的倒装：只有 were / should / had 能提前</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>含蓄虚拟与情态动词 + have done</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：先说出同一时空虚拟的三行形式，再用“先圈时间词”的方法讲一道错综时间题的做法。</p><div class="hint-container tip"><p class="hint-container-title">同一时空：现、过、将来三行表</p><p><strong>句意</strong>：If I were you, I would consider their advice. 意思是“如果我是你，我会考虑他们的建议”。</p><p><strong>拆解</strong></p><ul><li>与现在事实相反：从句 did/were，主句 would/should/could/might + do</li><li>与过去事实相反：从句 had done，主句 would + have done（If I had had more money, I would have bought a new car.）</li><li>与将来事实相反：从句 did/were to do/should do，主句 would + do</li><li>If I were you 里的 were 不随人称变化：不管主语是谁都用 were</li></ul><p><strong>语法</strong>：if 条件句虚拟按“与哪个时间的事实相反”分三格：现在（did/were + would do）、过去（had done + would have done）、将来（did/were to do/should do + would do）。</p><ol><li>与现在相反：从句用过去式 —→ 主句 would + do</li><li>与过去相反：从句用过去完成时 —→ 主句 would have done</li><li>与将来相反：从句用过去式 / were to do —→ 主句 would + do</li></ol><p>正例：If I were you, I would consider their advice.；If I had had more money, I would have bought a new car.；If I had more money in the future, I would buy a new car. 反例：If I was you, I would consider their advice. ×（与现在相反时 be 一律 were）；If I had more money, I would have bought a new car. ×（从句说现在、主句说过去，两半时间错位） 适用边界：先定时间再套形式：句中的时间词（now、last year、next month）决定用哪一行，不能只凭“虚拟”两个字就随便挑。</p><p><strong>口诀</strong>：现在过去式，过去完成时，将来 would do —— 两半要配套：从句与主句各自对应同一个时间，才算同一时空虚拟。</p></div><div class="hint-container tip"><p class="hint-container-title">错综时间：各看各的时间标志</p><p><strong>句意</strong>：If you had left earlier, you would be at the concert now. 意思是“如果你早点出发，你现在就在演唱会上了”。</p><p><strong>拆解</strong></p><ul><li>从句有 earlier（过去），所以用 had left</li><li>主句有 now（现在），所以用 would be，而不是 would have been</li><li>If you followed my advice now, you would succeed in the final exam next month.：从句现在、主句将来</li><li>If you had done your homework yesterday, you would know how to answer the question now.：从句过去、主句现在</li></ul><p><strong>语法</strong>：错综时间虚拟：从句和主句分别对应不同时间时，各按自己的时间选动词形式；不要整句只套一列。</p><ol><li>从句：had done，对应 earlier / yesterday 这样的过去标志</li><li>主句：would + do，对应 now 这样的现在标志</li></ol><p>正例：If you had left earlier, you would be at the concert now.；If you had done your homework yesterday, you would know how to answer the question now.；If you followed my advice now, you would succeed in the final exam next month. 反例：If you had left earlier, you would have been at the concert now. ×（now 指现在，主句该用 would be）；If you followed my advice now, you would have succeeded next month. ×（now 与 next month 混在一列里，形式配错） 适用边界：先圈时间词再动笔：从句前面的 before/yesterday/earlier 与主句后面的 now/next month 是两套时间，必须分开处理。</p><p><strong>口诀</strong>：各看各的时间，各用各的虚拟 —— 一句里出现两个时间标志，就按两个时间分别配形式。</p></div><div class="hint-container tip"><p class="hint-container-title">省略 if 的倒装：只有 were / should / had 能提前</p><p><strong>句意</strong>：Had you taken my advice, you wouldn&#39;t have failed in the examination. 意思是“如果你当时听了我的建议，就不会考试不及格了”。</p><p><strong>拆解</strong></p><ul><li>原句 If you had taken my advice 省略 if、把 had 提到主语前 → Had you taken...</li><li>Were I you... = If I were you...；Should it rain... = If it should rain...</li><li>were it not for 表“要不是因为”，对现在虚拟；had it not been for 对过去虚拟</li><li>不能把普通实义动词直接提前：不能说 Took you my advice</li></ul><p><strong>语法</strong>：if 从句含 were、should、had 时，可省略 if 并把这三个词移到主语之前；were it not for / had it not been for 表示“要不是因为……”。</p><ol><li>were → 对现在虚拟（Were I you...）</li><li>had been → 对过去虚拟（Had it not been for...）</li><li>should → 对将来虚拟（Should it rain...）</li></ol><p>正例：Were I you, I would apply for the job.；Had you taken my advice, you wouldn&#39;t have failed in the examination.；Had it not been for your help, I would have gone bankrupt. 反例：Took you my advice, you wouldn&#39;t have failed. ×（只有 were/should/had 能提前）；Were it not for your help, I would have gone bankrupt. ×（对过去虚拟要用 had it not been for） 适用边界：倒装只搬运 were、should、had 三个词；句子里出现的是普通动词时，只能用 If… 的形式，不能倒装。</p><p><strong>口诀</strong>：were、should、had 才能提，省 if 后放句首 —— 先找这三个词，有就倒装，没有就老老实实写 if。</p></div><div class="hint-container tip"><p class="hint-container-title">含蓄虚拟与情态动词 + have done</p><p><strong>句意</strong>：But for your advice, I would have failed. 意思是“要不是你的建议，我就失败了”；You should have told me the truth earlier. 意思是“你本应该早点告诉我真相”。</p><p><strong>拆解</strong></p><ul><li>without、but for 直接引出条件：Without air, there wouldn&#39;t be living things in the world.</li><li>otherwise / or 承接前一句的事实，后面用虚拟主句：He came to town yesterday; otherwise I would not have met him.</li><li>should have done 过去本应做而未做；shouldn&#39;t have done 本不应做却做了</li><li>could have done 本来能够却没做；needn&#39;t have done 本不必做却做了；would rather have done 宁愿过去做了</li></ul><p><strong>语法</strong>：假设条件可用 without、but for、otherwise、or 等表达，相当于 if 条件句的主句虚拟；情态动词 + have done 表示对过去的“本来……却……”。must、can、may 本身不用于这类结构。</p><ol><li>对现在虚拟：would + do（Without air, there wouldn&#39;t be living things.）</li><li>对过去虚拟：would have done（But for your advice, I would have failed.）</li></ol><p>正例：Without air, there wouldn&#39;t be living things in the world.；But for your advice, I would have failed.；You should have told me the truth earlier.；You needn&#39;t have watered the flowers. It&#39;s going to rain. 反例：But for your advice, I would fail. ×（这里是“当时”的假设，要用 would have failed）；You must have told me the truth earlier. ×（“本应该”用 should have done，must have done 表肯定推测） 适用边界：先看有没有 if：没有 if 却出现 would/should + have done，就要回头找含蓄条件（without、but for、otherwise、or）。</p><p><strong>口诀</strong>：should 本应该，needn&#39;t 本不必，could 本能够 —— 情态动词 + have done 都指向“过去没实现的那一步”，记住每个情态词自带的态度即可。</p></div><h3 id="_1-同一时空虚拟" tabindex="-1"><a class="header-anchor" href="#_1-同一时空虚拟"><span>1. 同一时空虚拟</span></a></h3><table><thead><tr><th>与事实相反的时间</th><th>if 从句</th><th>主句</th></tr></thead><tbody><tr><td><strong>现在</strong></td><td>did / were</td><td>would/should/could/might + do</td></tr><tr><td><strong>过去</strong></td><td>had done</td><td>would/should/could/might + have done</td></tr><tr><td><strong>将来</strong></td><td>did / were to do / should do</td><td>would/should/could/might + do</td></tr></tbody></table><p><strong>与现在事实相反：</strong></p><p>If I <strong>had</strong> more money, I <strong>would buy</strong> a new car.（如果我有更多的钱，我会买一辆新车。） If I <strong>were</strong> you, I <strong>would consider</strong> their advice.（如果我是你，我会考虑他们的建议。）</p><p><strong>与过去事实相反：</strong></p><p>If I <strong>had had</strong> more money, I <strong>would have bought</strong> a new car.（如果我当时有更多的钱，我就会买一辆新车了。） You <strong>would not have caught</strong> a cold if you <strong>had put on</strong> more clothes.（如果你当时多穿点衣服，就不会感冒了。）</p><p><strong>与将来事实相反：</strong></p><p>If I <strong>had</strong> more money in the future, I <strong>would buy</strong> a new car, but it&#39;s unlikely.（如果将来我有更多的钱，我会买一辆新车，但这不太可能。）</p><h3 id="_2-错综时间虚拟" tabindex="-1"><a class="header-anchor" href="#_2-错综时间虚拟"><span>2. 错综时间虚拟</span></a></h3><p>从句和主句分别对应不同时间，就<strong>分别按各自所反事实的时间</strong>选择动词形式。</p><p>If you <strong>had left</strong> earlier, you <strong>would be</strong> at the concert now.（如果你早点出发，你现在就在演唱会上了。——过去条件 + 现在结果） If you <strong>had worked</strong> hard before, you <strong>would be</strong> very tired now.（如果你以前努力工作，你现在会很累。——过去条件 + 现在结果） If you <strong>followed</strong> my advice now, you <strong>would succeed</strong> in the final exam next month.（如果你现在听从我的建议，你下个月的期末考试就会成功。——现在条件 + 将来结果）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>做题方法句子各部分是什么时间，就判断其与哪个时间的事实相反，再分别套用该时间的动词形式，<strong>不要整句只套一列</strong>。</p></div><h3 id="_3-虚实混用" tabindex="-1"><a class="header-anchor" href="#_3-虚实混用"><span>3. 虚实混用</span></a></h3><p>有的部分是真实事实，有的部分是虚拟情况。<strong>非真实部分才虚拟，真实部分使用正常时态</strong>。</p><p>If I <strong>had been</strong> at the concert yesterday evening, I <strong>should have met</strong> the famous singer. But I failed to get a ticket.（如果我昨晚在音乐会上，就会见到那位著名歌手了。但我没能买到票。——前句是过去虚拟；&quot;没买到票&quot;是真实发生的事实）</p><h3 id="_4-省略-if-的倒装" tabindex="-1"><a class="header-anchor" href="#_4-省略-if-的倒装"><span>4. 省略 if 的倒装</span></a></h3><p>if 从句含 <strong>were、should、had</strong> 时，可以省略 if，并把 were、should、had 移到主语之前：</p><table><thead><tr><th>原句</th><th>倒装</th></tr></thead><tbody><tr><td>If I <strong>were</strong> you...</td><td><strong>Were I you</strong>...</td></tr><tr><td>If you <strong>had</strong> taken...</td><td><strong>Had you taken</strong>...</td></tr><tr><td>If it <strong>should</strong> rain...</td><td><strong>Should it rain</strong>...</td></tr></tbody></table><p>If I were you, I would apply for the job. = <strong>Were I you, I would apply for the job.</strong>（如果我是你，我会申请这份工作。） If you had taken my advice, you wouldn&#39;t have failed in the examination. = <strong>Had you taken my advice, you wouldn&#39;t have failed in the examination.</strong>（如果你当时听了我的建议，就不会考试不及格了。）</p><p><strong>were it not for / had it not been for</strong> 表示&quot;要不是因为……&quot;：</p><p>If it were not for peace, we could not live a happy life. = <strong>Were it not for peace, we could not live a happy life.</strong>（如果不是因为和平，我们就不能过上幸福生活。） If it had not been for your help, I would have gone bankrupt. = <strong>Had it not been for your help, I would have gone bankrupt.</strong>（如果当时不是因为你的帮助，我就破产了。）</p><h3 id="_5-含蓄虚拟" tabindex="-1"><a class="header-anchor" href="#_5-含蓄虚拟"><span>5. 含蓄虚拟</span></a></h3><p>假设条件不一定写成 if 从句，也可由介词或介词短语 <strong>without、but for</strong>，副词 <strong>otherwise</strong>，连词 <strong>or、but</strong> 等表达；此时可看成 if 条件句的主句虚拟结构。</p><p><strong>Without air</strong>, there wouldn&#39;t be living things in the world.（没有空气，世界上就不会有生物。） <strong>But for your advice</strong>, I would have failed.（要不是你的建议，我就失败了。） He came to town yesterday; <strong>otherwise/or I would not have met him</strong>.（他昨天进城了，否则我就见不到他了。）</p><h3 id="_6-情态动词-have-done" tabindex="-1"><a class="header-anchor" href="#_6-情态动词-have-done"><span>6. 情态动词 + have done</span></a></h3><table><thead><tr><th>形式</th><th>含义</th><th>例句</th></tr></thead><tbody><tr><td>should have done</td><td>过去本应该做，实际没做</td><td>You <strong>should have told</strong> me the truth earlier.（你本应该早点告诉我真相。）</td></tr><tr><td>shouldn&#39;t have done</td><td>过去本不应该做，实际做了</td><td>You <strong>shouldn&#39;t have stayed up</strong> so late last night.（你昨晚本不应该熬夜到这么晚。）</td></tr><tr><td>could have done</td><td>过去本有能力或机会做，实际没做</td><td>He <strong>could have won</strong> the race if he had tried harder.（如果他更努力些，本可以赢得比赛。）</td></tr><tr><td>couldn&#39;t have done</td><td>对过去事情的否定推测：不可能做过</td><td>He <strong>couldn&#39;t have finished</strong> the work in such a short time.（他不可能在这么短的时间内完成这项工作。）</td></tr><tr><td>would have done</td><td>与过去事实相反：某条件下本会做</td><td>I <strong>would have gone</strong> to the party if I had been invited.（如果我被邀请了，本来会去参加派对。）</td></tr><tr><td>wouldn&#39;t have done</td><td>某条件下本不会做</td><td>She <strong>wouldn&#39;t have bought</strong> that dress if she hadn&#39;t seen the discount.（如果没看到折扣，她本来不会买那条裙子。）</td></tr><tr><td>might have done</td><td>过去可能做了，是否做过不确定</td><td>He <strong>might have forgotten</strong> about our appointment.（他也许忘了我们的约会。）</td></tr><tr><td>might not have done</td><td>过去可能没做</td><td>They <strong>might not have received</strong> our email yet.（他们也许还没收到我们的邮件。）</td></tr><tr><td>need have done</td><td>过去本有必要做，实际没有做</td><td>You <strong>need have come</strong> here earlier. There was a lot of preparation work.（你本有必要早点来，这里有很多准备工作。）</td></tr><tr><td>needn&#39;t have done</td><td>过去本没必要做，实际做了</td><td>You <strong>needn&#39;t have watered</strong> the flowers. It&#39;s going to rain.（你本没必要浇花，马上要下雨了。）</td></tr><tr><td>would rather have done</td><td>宁愿过去做了，实际没做；或后悔没做</td><td>I <strong>would rather have stayed</strong> at home last night. The party was boring.（我昨晚宁愿待在家里；那个派对太无聊了。）</td></tr><tr><td>would rather not have done</td><td>宁愿过去没做，实际做了</td><td>She <strong>would rather not have said</strong> those words.（她宁愿自己当时没说那些话。）</td></tr><tr><td>would like/love to have done</td><td>过去本想做，实际没做</td><td>I <strong>would like to have visited</strong> the museum last week.（我上周本想去参观博物馆。）</td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">易错</p><p>课件提示<strong>must、can、may 本身不用于表达这种&quot;本来……却……&quot;的虚拟结构；但 could/might have done 可表达未实现的可能性或推测。</strong></p></div><h2 id="第四部分-·-特殊虚拟结构" tabindex="-1"><a class="header-anchor" href="#第四部分-·-特殊虚拟结构"><span>第四部分 · 特殊虚拟结构</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第四部分 · 特殊虚拟结构</p><ul><li><strong>目标</strong>：解决 It is (high/about) time 这一类“该做某事了”的写法，并把它的 should 与 (should) be 型里可省的 should 区分开。</li><li><strong>建议用时</strong>：10 分钟</li><li><strong>知识点</strong>：<code>It is (high/about) time + 从句</code></li></ul></div><h3 id="第四部分-·-特殊虚拟结构-·-小步学" tabindex="-1"><a class="header-anchor" href="#第四部分-·-特殊虚拟结构-·-小步学"><span>第四部分 · 特殊虚拟结构 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 0 道原课题；完整练习保留在下方原课内容。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>虚拟语气：表达设想、愿望或建议</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>It is (high/about) time + 过去式，should 不可省</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li></ol></details><p><strong>自己说一遍</strong>：把 It is high time 的两种写法各说一遍，并指出 should 在这里能不能省、为什么。</p><div class="hint-container tip"><p class="hint-container-title">It is (high/about) time + 过去式，should 不可省</p><p><strong>句意</strong>：It is high time we went to bed. = It is high time we should go to bed. 意思是“我们该睡觉了”。</p><p><strong>拆解</strong></p><ul><li>主句 It is high time 表示“早就该……了”，本身没有实际动作</li><li>从句 we went 用一般过去时表虚拟，不能说 we go</li><li>也可以写 we should go，但这个 should 不能省略</li><li>It&#39;s high time that you realized the seriousness of your own mistakes. 是同一条规则的真题例子</li></ul><p><strong>语法</strong>：在 It is (high/about) time + 从句中，从句谓语用一般过去时，或用 should + 动词原形（should 不可省略），表示“该做某事的时候到了”。</p><ol><li>说话时刻在现在</li><li>从句用一般过去时，表示“与现在的实情有距离”：现在还没做，所以才说该做了</li></ol><p>正例：It is high time we went to bed.；It is high time we should go to bed.；It&#39;s high time that you realized the seriousness of your own mistakes. 反例：It is high time we go to bed. ×（从句用一般过去时）；It is high time we go/should to bed… ×（should 后要接动词原形，且这里的 should 不能省） 适用边界：别把两类 structure 混在一起：(should) be 型里的 should 通常可以省；It is time 里的 should 不能省，而且更常见的写法是直接用过去式。另外 It is the first time that… 用的是现在完成时，不是虚拟。</p><p><strong>口诀</strong>：It is time 用过去，should 不能省 —— 先认出 It is (high) time 这个标志框架，再决定写过去式还是 should + 原形。</p></div><p>在 <strong>It is (high/about) time + 从句</strong> 中，从句谓语用<strong>一般过去时</strong>，或用 <strong>should + 动词原形</strong>（此处 should 不可省略），表示&quot;该做某事的时候到了&quot;。</p><p>It is high time we <strong>went</strong> to bed. = It is high time we <strong>should go</strong> to bed.（我们该睡觉了。）</p><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p>suggest/insist 要先看词义：建议、要求才虚拟；&quot;表明&quot;&quot;坚持说&quot;不用虚拟</p></li><li><p>(should) be 型里的 should 通常可省，但 <strong>It is time... should do 中的 should 不可省</strong></p></li><li><p>与现在事实相反时，be 不随人称变化，统一用 <strong>were</strong></p></li><li><p>wish/if only/would rather 后的&quot;过去式&quot;表示与事实的距离，不等于句子一定发生在过去</p></li><li><p>错综时间题必须分别找从句和主句的时间标志，如 before/yesterday 与 now/next month</p></li><li><p>省略 if 倒装只提前 <strong>were、should、had</strong>，不能把普通实义动词直接提前</p></li><li><p><strong>were it not for</strong> 对现在虚拟；<strong>had it not been for</strong> 对过去虚拟</p></li><li><p>should have done = 本应做而未做；needn&#39;t have done = 本不必做却做了</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>The job would require that ____ at 7 o’clock every morning. （这份工作要求他每天早上七点到工厂。）</strong></p><ul><li>A. he will be at the factory</li><li>B. he be at the factory</li><li>C. he was at the factory</li><li>D. he has been at the factory</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（he be at the factory）</strong> —— require 后的 that 从句用 (should) be，should 可省略。（(should) be 型随堂练习）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will be 是陈述语气的将来时；require 后的 that 从句要用 (should) + 动词原形，不按真实时态走。干扰点：把从句当普通宾语从句处理。</li><li>B ✅ require 属于“四个要求”，从句用 (should) be at the factory，should 省略后就写 he be at the factory。</li><li>C ❌ was 是过去时，既不是虚拟形式，也与“这份工作的要求”这一现在的设定不符。</li><li>D ❌ has been 是现在完成时，同样把从句写成了真实时态；require 从句要用原形 be。</li></ul><p><strong>整句翻译</strong>：这份工作要求他每天早上七点到工厂。</p><p><strong>词组</strong>：<code>require that ... (should) do</code> 要求……（从句用 (should) + 动词原形）；<code>at the factory</code> 在工厂</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 (should) be 型）：这些动词引导宾语从句时，从句谓语用：动词 + (that) + 从句主语 + (should) do / (should) be done</p></details><p><strong>Your advice that she ____ till next week is reasonable. （你建议她等到下周，这一建议很合理。）</strong></p><ul><li>A. will wait</li><li>B. is going to wait</li><li>C. waits</li><li>D. wait</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（wait）</strong> —— advice 后的同位语从句用 (should) wait。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will wait 是陈述语气的将来时；advice 后面的同位语从句要用 (should) + 动词原形。</li><li>B ❌ is going to wait 也是陈述语气，没有用虚拟形式。干扰点：以为“将来要发生”就要用将来时。</li><li>C ❌ waits 是第三人称单数的一般现在时，同样不是 (should) + 原形。</li><li>D ✅ advice 是 suggest 的名词形式，属于“四个建议”的变形词，后面的同位语从句用 (should) wait，should 省略后就是 wait。</li></ul><p><strong>整句翻译</strong>：你建议她等到下周，这一建议很合理。</p><p><strong>词组</strong>：<code>till next week</code> 直到下周；<code>reasonable</code> 合理的</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件变形词）：上述词变成名词、形容词等形式后，引导的主语从句、表语从句或同位语从句同样用 (should) + 动词原形</p></details><p><strong>It is necessary that a worker ____ his work on time. （工人按时完成工作是必要的。）</strong></p><ul><li>A. accomplishes</li><li>B. can accomplish</li><li>C. accomplish</li><li>D. has accomplished</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（accomplish）</strong> —— It is necessary that... 后用 (should) accomplish。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ accomplishes 是第三人称单数的一般现在时；necessary 后的从句要用 (should) + 动词原形。</li><li>B ❌ can accomplish 多了情态动词：(should) be 型里的 should 可以省略，但不能换成 can。干扰点：以为“能完成”更顺口。</li><li>C ✅ It is necessary that… 属于“必要性”类结构，从句用 (should) accomplish，should 省略后就是 accomplish。</li><li>D ❌ has accomplished 是现在完成时，把从句写成了真实时态。</li></ul><p><strong>整句翻译</strong>：工人按时完成工作是必要的。</p><p><strong>词组</strong>：<code>on time</code> 按时；<code>It is necessary that ... (should) do</code> ……是必要的（从句用原形）</p><p><strong>对比自测</strong>：做完后对照 quiz:0，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It is + 形容词）：表示必要性、重要性、强制性…时，that 从句用 (should) + 动词原形</p></details><p><strong>The government suggests people ____ the Spring Festival at their working place this year. （政府建议人们今年在工作地过春节。）</strong></p><ul><li>A. to spend</li><li>B. spend</li><li>C. spending</li><li>D. will spend</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（spend）</strong> —— suggest 表“建议”，从句用 (should) spend。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ suggest 后不接“宾语 + 不定式”，不说 suggest people to spend；这里需要一个从句谓语动词。干扰点：把 advise sb. to do 的结构套到 suggest 上。</li><li>B ✅ suggest 表“建议”，宾语从句用 (should) spend，should 省略后就是 spend。</li><li>C ❌ spending 是动名词，不能单独充当 that 从句的谓语。干扰点：记住 suggest doing 就以为从句也用 -ing。</li><li>D ❌ will spend 是陈述语气的将来时，与“建议”义的虚拟形式不符。</li></ul><p><strong>整句翻译</strong>：政府建议人们今年在工作地过春节。</p><p><strong>词组</strong>：<code>the Spring Festival</code> 春节；<code>at one&#39;s working place</code> 在工作地</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 suggest 特例）：suggest 表示“建议”时用虚拟；表示“暗示、表明、说明”时陈述客观事实，不用虚拟</p></details><p><strong>The physicists propose that our attention ____ the use of special methods of thinking and acting. （物理学家建议我们把注意力转向特殊思维和行动方法的运用。）</strong></p><ul><li>A. would be directed towards</li><li>B. be directed towards</li><li>C. is directed towards</li><li>D. direct towards</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（be directed towards）</strong> —— propose 表“建议”，attention 与 direct 是被动关系，用 (should) be directed。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ would be directed towards 是过去将来时的陈述语气；propose 后的从句要用 (should) + 动词原形，should 省掉后是 be directed。</li><li>B ✅ propose 属于“四个建议”，从句用 (should) be directed towards；attention 是被引导的对象，所以用被动。</li><li>C ❌ is directed towards 是一般现在时的陈述语气，没有用虚拟形式。</li><li>D ❌ direct towards 是主动态，attention 不会自己“引导”，而且缺了 (should) be。干扰点：只顾虚拟形式忘了语态。</li></ul><p><strong>整句翻译</strong>：物理学家建议我们把注意力转向特殊思维和行动方法的运用。</p><p><strong>词组</strong>：<code>propose that ... (should) do</code> 建议……（从句用原形）；<code>direct one&#39;s attention towards ...</code> 把注意力引向……（attention 与 direct 是被动关系）</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 (should) be 型）：被动结构为 (should) be + 过去分词</p></details><p><strong>The boy insisted that he ____ old enough, and ____ the right to make his own choice. （那个男孩坚持说自己年龄已经够大，并坚持要求得到自主选择的权利。）</strong></p><ul><li>A. was; be given</li><li>B. was; was given</li><li>C. be; give</li><li>D. is; given</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（was; be given）</strong> —— 第一个 insist 表“坚持说”，陈述事实用 was；第二个表“坚持要求”，用 (should) be given。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 第一个 insisted 表“坚持说”，从句陈述事实用 was；第二个表“坚持要求”，用 (should) be given，right 与 give 是被动关系。</li><li>B ❌ 第二个空写成 was given 是陈述语气，把“坚持要求得到权利”说成了陈述事实。</li><li>C ❌ 第一个空用 be 错了（“坚持说自己够大”是事实，用 was）；第二个空用 give 又丢了被动。</li><li>D ❌ is 是现在时，与 insisted 的过去语境不符；given 缺 be，不能单独作谓语。干扰点：只改了时态，没改成虚拟。</li></ul><p><strong>整句翻译</strong>：那个男孩坚持说自己年龄已经够大，并坚持要求得到自主选择的权利。</p><p><strong>词组</strong>：<code>old enough</code> 年龄够大；<code>make one&#39;s own choice</code> 自己做选择</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 suggest / insist 特例）：insist 表示“坚持要求”时用虚拟；表示“坚持说”时陈述事实，不用虚拟</p></details><p><strong>You are overweight. You’d better ____ any junk food. I suggest you ____ more vegetables. （你超重了。你最好不要吃垃圾食品；我建议你多吃蔬菜。）</strong></p><ul><li>A. not to eat; to have</li><li>B. not eat; have</li><li>C. not eat; to have</li><li>D. not to eat; have</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（not eat; have）</strong> —— had better 后接动词原形，否定为 had better not do；suggest 从句用 (should) have。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ had better 后接动词原形，不说 had better not to eat；suggest you to have 也不是 suggest 的用法。</li><li>B ✅ had better 后接动词原形、否定直接加 not → not eat；suggest 从句用 (should) have，should 省略后就是 have。</li><li>C ❌ 第二空写成 to have 错了：suggest 后面的从句要用 (should) + 动词原形，不能接不定式。</li><li>D ❌ 第一空 not to eat 多了 to：had better 后面永远接动词原形。</li></ul><p><strong>整句翻译</strong>：你超重了。你最好不要吃垃圾食品；我建议你多吃蔬菜。</p><p><strong>词组</strong>：<code>had better (not) do sth.</code> 最好（不）做某事；<code>junk food</code> 垃圾食品</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 (should) be 型）：suggest 表示“建议”时用虚拟；表示“暗示、表明、说明”时陈述客观事实，不用虚拟</p></details><p><strong>I enjoyed the movie very much. I wish I ____ the book from which it was made. （我很喜欢这部电影，真希望自己读过它所改编自的那本书。）</strong></p><ul><li>A. have read</li><li>B. had read</li><li>C. should have read</li><li>D. are reading</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（had read）</strong> —— wish 针对过去未发生之事，使用 had done。（were 型随堂练习）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ have read 是真实的现在完成时，而 wish 从句要表达“事实并非如此”。</li><li>B ✅ “读过那本书”是与过去事实相反的愿望，用过去完成时 had read。</li><li>C ❌ should have read 表“本应该读”，是情态动词的遗憾语气，不用于 wish 从句表“真希望曾经读过”。干扰点：把“本应该”与“希望曾经”混为一谈。</li><li>D ❌ are reading 是现在进行时，与 wish 从句要求的虚拟形式不符。</li></ul><p><strong>整句翻译</strong>：我很喜欢这部电影，真希望自己读过它所改编自的那本书。</p><p><strong>词组</strong>：<code>from which it was made</code> 电影由它改编而来（介词 + which 定语从句）；<code>I wish I had done sth.</code> 真希望自己做过某事（与过去事实相反）</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 wish）：I wish that I had passed the final exam.（我真希望自己已经通过了期末考试。——与过去事实相反，实际未通过）</p></details><p><strong>The two students talked as if they ____ friends for years. （两名学生交谈起来，好像已经做了多年朋友。）</strong></p><ul><li>A. should be</li><li>B. would be</li><li>C. have been</li><li>D. had been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（had been）</strong> —— “做了多年朋友”先于 talked，用 had been。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ should be 不用于 as if 从句表“与过去相反”的情况。干扰点：把 (should) be 型的形式挪到 as if 从句里。</li><li>B ❌ would be 表与将来相反，而 for years 说的是谈话之前的这些年。</li><li>C ❌ have been 是真实的现在完成时；as if 所述与事实相反时要用虚拟。</li><li>D ✅ “做了多年朋友”先于 talked，与过去事实相反，用过去完成时 had been。</li></ul><p><strong>整句翻译</strong>：两名学生交谈起来，好像已经做了多年朋友。</p><p><strong>词组</strong>：<code>as if</code> 仿佛、好像（所述与事实相反时用虚拟）；<code>for years</code> 多年（提示动作早于主句）</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 as if）：He talked about the film as if he had seen it before.</p></details><p><strong>If only he ____ quietly as the doctor instructed, he would not suffer so much now. （要是他当时按医生嘱咐静静躺着就好了，他现在就不会受这么多罪。）</strong></p><ul><li>A. lies</li><li>B. lay</li><li>C. had lain</li><li>D. should lie</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（had lain）</strong> —— 从句与过去事实相反，主句结果落在现在，是错综时间虚拟。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ lies 是真实的现在时，if only 从句要用虚拟语气。</li><li>B ❌ lay 是一般过去时，只能对现在虚拟；本句“当时没照做”是过去的事，要用 had done。</li><li>C ✅ 从句与过去事实相反用 had lain；主句落在现在（would not suffer now），是错综时间虚拟。</li><li>D ❌ should lie 表对将来的假设，与 as the doctor instructed（已发生）的时间不符。干扰点：看到 should 就以为该选它。</li></ul><p><strong>整句翻译</strong>：要是他当时按医生嘱咐静静躺着就好了，他现在就不会受这么多罪。</p><p><strong>词组</strong>：<code>as the doctor instructed</code> 按医生的嘱咐（提示从句指过去）；<code>suffer</code> 受苦、受罪</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 if only）：If only I hadn’t made this mistake.（要是我没有犯这个错误就好了。——与过去事实相反）</p></details><p><strong>“He will come tomorrow.” “But I’d rather he ____ the day after tomorrow.” （“他明天会来。”“但我宁愿他后天来。”）</strong></p><ul><li>A. will come</li><li>B. is coming</li><li>C. came</li><li>D. had come</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（came）</strong> —— would rather 后对将来愿望用一般过去时。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will come 是真实将来时；would rather 后的从句要用过去式表愿望。</li><li>B ❌ is coming 是现在进行时表将来，同样不是虚拟形式。</li><li>C ✅ would rather 从句对现在或将来的愿望用一般过去时 came（他实际明天来，我希望后天来）。</li><li>D ❌ had come 表对过去的愿望，与 the day after tomorrow 的时间不符。干扰点：见到“过去形式”就选完成时。</li></ul><p><strong>整句翻译</strong>：“他明天会来。”“但我宁愿他后天来。”</p><p><strong>词组</strong>：<code>would rather (that) sb. did sth.</code> 宁愿某人做某事（从句用过去式）；<code>the day after tomorrow</code> 后天</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 would rather）：从句用一般过去时表示现在或将来的愿望，用过去完成时表示对过去的愿望</p></details><p><strong>The sun rises in the east and sets in the west, so it seems as if the sun ____ round the earth. （太阳东升西落，因此看起来仿佛太阳在绕着地球转。）</strong></p><ul><li>A. were circling</li><li>B. circles</li><li>C. is circling</li><li>D. be circling</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（were circling）</strong> —— as if 描述与事实相反的表象，be 用 were，动作表进行。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ as if 所述与事实相反（太阳并不绕地球转），be 用 were，动作表进行用 circling。</li><li>B ❌ circles 是陈述事实；而从句讲的正是与事实相反的表象。</li><li>C ❌ is circling 是真实的现在进行时，没有用虚拟。</li><li>D ❌ be circling 少了虚拟的标志——as if 从句的虚拟用过去式形式（were），不是动词原形。干扰点：把 (should) be 型的原形规则用到这里。</li></ul><p><strong>整句翻译</strong>：太阳东升西落，因此看起来仿佛太阳在绕着地球转。</p><p><strong>词组</strong>：<code>rise in the east and set in the west</code> 东升西落；<code>as if</code> 仿佛（所述与事实相反时用虚拟）</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 as if）：所述情况与事实相反或极不可能发生</p></details><p><strong>If I ____ where he lived now, I ____ a note to him. （如果我现在知道他住在哪里，就会给他寄张便条。）</strong></p><ul><li>A. knew; would send</li><li>B. had known; would have sent</li><li>C. know; would send</li><li>D. knew; would have sent</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（knew; would send）</strong> —— now 指向现在：if 从句用 knew，主句用 would send。（同一时空随堂练习）</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ now 指向现在：从句用 knew，主句用 would send，两半都在“现在”这一格。</li><li>B ❌ had known / would have sent 是对过去的虚拟，与 now 的时间标志冲突。</li><li>C ❌ know 是真实条件句的形式，主句却是虚拟的 would send，前后不一致。</li><li>D ❌ 从句 knew（现在虚拟）对，但主句 would have sent 是过去虚拟的结果，两半时间对不上。</li></ul><p><strong>整句翻译</strong>：如果我现在知道他住在哪里，就会给他寄张便条。</p><p><strong>词组</strong>：<code>send a note to sb.</code> 给某人寄便条；<code>live</code> 居住</p><p><strong>对比自测</strong>：做完后对照 quiz:13，比较两题的判断依据</p><p><strong>原文定位</strong>（课件同一时空虚拟）：If I were you, I would consider their advice.（如果我是你，我会考虑他们的建议。）</p></details><p><strong>If we ____ more time, we could do it better. （如果给我们更多时间，我们能把它做得更好。）</strong></p><ul><li>A. were given</li><li>B. are given</li><li>C. is given</li><li>D. is giving</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（were given）</strong> —— 与现在事实相反，we 与 give 是被动关系，用 were given。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 与现在事实相反，we 与 give 是被动关系，用 were given。</li><li>B ❌ are given 是真实条件句的形式；主句的 could do 已经表明这是虚拟。</li><li>C ❌ is given 既是单数（主语是 we），又没有用虚拟。</li><li>D ❌ is giving 是主动进行，we 不会“给予自己”时间；语态和数都错。</li></ul><p><strong>整句翻译</strong>：如果给我们更多时间，我们能把它做得更好。</p><p><strong>词组</strong>：<code>more time</code> 更多时间；<code>do it better</code> 把它做得更好</p><p><strong>对比自测</strong>：做完后对照 quiz:12，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与现在事实相反）：If I were you, I would consider their advice.</p></details><p><strong>If I ____ a boss, I would manage a big factory. （如果我是老板，我会管理一家大工厂。）</strong></p><ul><li>A. are</li><li>B. was</li><li>C. were</li><li>D. be</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（were）</strong> —— 与现在事实相反，be 一律用 were。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ are 是真实条件句的形式，主句的 would manage 说明这是虚拟。</li><li>B ❌ was 在虚拟句里同样不行：与现在事实相反时 be 不随人称变化，一律用 were。干扰点：以为只有 I 才用 were。</li><li>C ✅ 与现在事实相反，be 一律用 were：If I were a boss。</li><li>D ❌ be 是 (should) be 型虚拟的形式，不属于 if 虚拟条件句。</li></ul><p><strong>整句翻译</strong>：如果我是老板，我会管理一家大工厂。</p><p><strong>词组</strong>：<code>manage a factory</code> 管理一家工厂；<code>a big factory</code> 一家大工厂</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与现在事实相反）：与现在事实相反时，be 不随人称变化，统一用 were</p></details><p><strong>If I ____ not so busy, I ____ with you. （如果我没这么忙，我就会和你一起去。）</strong></p><ul><li>A. was; would go</li><li>B. were; would go</li><li>C. was; should go</li><li>D. were; will go</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（were; would go）</strong> —— 从句 were，主句 would go。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 从句 was 不符：与现在事实相反时 be 一律用 were。</li><li>B ✅ 从句 were，主句 would go，两半都是“与现在事实相反”的标准形式。</li><li>C ❌ should go 在英式英语里可表第一人称的虚拟结果，但本句的错点在从句 was（应为 were），所以整个选项不成立。</li><li>D ❌ will go 是真实将来时，主句该用 would + 动词原形。</li></ul><p><strong>整句翻译</strong>：如果我没这么忙，我就会和你一起去。</p><p><strong>词组</strong>：<code>so busy</code> 这么忙；<code>go with sb.</code> 和某人一起去</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与现在事实相反）：If I had more money, I would buy a new car.</p></details><p><strong>— If he ____, he ____ that food. — Luckily he was sent to the hospital immediately. （- 如果他事先得到警告，就不会吃那种食物了。- 幸运的是，他立刻被送往医院。）</strong></p><ul><li>A. was warned; would not take</li><li>B. had been warned; would not have taken</li><li>C. would be warned; had not taken</li><li>D. would have been warned; had not taken</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（had been warned; would not have taken）</strong> —— 对过去虚拟：had been warned / would not have taken。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ was warned 是真实的过去被动，主句 would not take 也不是过去虚拟的形式。</li><li>B ✅ 对过去虚拟：从句 had been warned（被动），主句 would not have taken。</li><li>C ❌ 把从句写成 would be warned、主句写成 had not taken，两半的形式互换了。干扰点：分不清哪半是条件、哪半是结果。</li><li>D ❌ 同样颠倒：条件从句该用 had done，主句该用 would have done。</li></ul><p><strong>整句翻译</strong>：“如果他事先得到警告，就不会吃那种食物了。”“幸运的是，他立刻被送往医院。”</p><p><strong>词组</strong>：<code>be warned</code> 被警告（被动）；<code>be sent to hospital</code> 被送往医院</p><p><strong>对比自测</strong>：做完后对照 quiz:17，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与过去事实相反）：If I had had more money, I would have bought a new car.</p></details><p><strong>If I ____ harder when I was young, I ____ a university and lived a different life. （如果我年轻时更加努力，我就会考上大学，过上不同的生活。）</strong></p><ul><li>A. worked; would entered</li><li>B. had worked; would have entered</li><li>C. would worked; had entered</li><li>D. have worked; will have entered</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（had worked; would have entered）</strong> —— when I was young 指过去：had worked / would have entered。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ worked 是真实过去时；would entered 还多一处错——would 后必须接 have entered，不能直接接过去式。</li><li>B ✅ when I was young 指过去，与过去事实相反：从句 had worked，主句 would have entered。</li><li>C ❌ would worked 语法不成立（would 后接原形），主从句的形式也颠倒了。</li><li>D ❌ have worked 是现在完成时、will have entered 是将来完成时，时间全错。</li></ul><p><strong>整句翻译</strong>：如果我年轻时更加努力，我就会考上大学，过上不同的生活。</p><p><strong>词组</strong>：<code>when I was young</code> 我年轻时（提示与过去事实相反）；<code>live a different life</code> 过着不同的生活</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与过去事实相反）：If I had had more money, I would have bought a new car.（如果我当时有更多的钱，我就会买一辆新车了。）</p></details><p><strong>Without the air to hold some of the sun’s heat, the earth at night ____ for us to live. （如果没有空气留住太阳的部分热量，夜晚的地球对我们而言会冷得无法生存。）</strong></p><ul><li>A. would be freezing cold</li><li>B. will be freezing coldly</li><li>C. would be frozen cold</li><li>D. can freeze coldly</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（would be freezing cold）</strong> —— without 引出与现在事实相反的含蓄条件，主句用 would + do；freezing cold 表“极冷”。（综合练习）</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ without 引出与现在事实相反的含蓄条件，主句用 would + 动词原形；freezing cold 是“极冷”的固定说法。</li><li>B ❌ will be 是真实将来时，没有虚拟；coldly 又是副词，不能作表语。</li><li>C ❌ frozen cold 不是固定搭配：frozen 指“冻僵的、冷冻的”，说“冷得结冰”要用 freezing cold。</li><li>D ❌ can freeze coldly 表“能够冷地结冰”，语义不通，coldly 也用错了词性。</li></ul><p><strong>整句翻译</strong>：如果没有空气留住太阳的部分热量，夜晚的地球对我们而言会冷得无法生存。</p><p><strong>词组</strong>：<code>hold heat</code> 留住热量；<code>freezing cold</code> 极冷（固定表达）</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件含蓄虚拟）：Without air, there wouldn&#39;t be living things in the world.</p></details><p><strong>Without electronic computers, much of today’s advanced technology ____. （如果没有电子计算机，当今许多先进技术就不可能实现。）</strong></p><ul><li>A. will not have been achieved</li><li>B. have not been achieved</li><li>C. would not have been achieved</li><li>D. had not been achieved</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（would not have been achieved）</strong> —— 技术已经实现，假设与过去事实相反，用 would not have been achieved。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ will not have been achieved 是将来完成时，不是虚拟。</li><li>B ❌ have not been achieved 是真实的现在完成时，语义会变成“技术还没实现”，与事实相反。</li><li>C ✅ 这些技术已经实现，假设与过去事实相反，主句用 would not have been achieved（被动）。</li><li>D ❌ had not been achieved 是过去完成时的陈述形式，不能充当虚拟主句的谓语。</li></ul><p><strong>整句翻译</strong>：如果没有电子计算机，当今许多先进技术就不可能实现。</p><p><strong>词组</strong>：<code>electronic computers</code> 电子计算机；<code>advanced technology</code> 先进技术</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件含蓄虚拟）：But for your advice, I would have failed.</p></details><p><strong>Yesterday, the storm delayed us. ____ the storm, we would have been here in time. （昨天暴风雨耽误了我们。要不是暴风雨，我们本来会及时到达这里。）</strong></p><ul><li>A. But for</li><li>B. If it were not for</li><li>C. If it is not for</li><li>D. Unless</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（But for）</strong> —— yesterday 和 would have been 表过去虚拟，But for = If it had not been for。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ yesterday 与 would have been 表明是对过去的虚拟，But for = If it had not been for the storm，后面直接接名词短语。</li><li>B ❌ If it were not for 是对现在的虚拟（were），与 yesterday 的时间不符。</li><li>C ❌ If it is not for 是真实条件句的形式，英语里也没有这个固定结构；对过去要说 If it had not been for。</li><li>D ❌ Unless 是连词，后面要接完整句子，不能直接接名词短语 the storm。干扰点：把“要不是”与“除非”混为一谈。</li></ul><p><strong>整句翻译</strong>：昨天暴风雨耽误了我们。要不是暴风雨，我们本来会及时到达这里。</p><p><strong>词组</strong>：<code>But for ...</code> 要不是……（= If it had not been for，后接名词）；<code>in time</code> 及时</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件含蓄虚拟）：But for your advice, I would have failed.</p></details><p><strong>Luckily, he wasn’t driving fast at the time of the accident; otherwise, I am sure, it ____ a more serious accident. （幸运的是，事故发生时他车开得不快；否则我敢肯定，那会成为一起更严重的事故。）</strong></p><ul><li>A. would be</li><li>B. were</li><li>C. would have been</li><li>D. had been</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（would have been）</strong> —— otherwise 指过去相反结果，用 would have been。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ would be 是对现在的虚拟结果，而 otherwise 承接的是事故当时的事实。</li><li>B ❌ were 是虚拟条件从句里的形式，不能作主句谓语。干扰点：只要有 were 就往虚拟上靠。</li><li>C ✅ otherwise 指与过去相反的结果：他当时开得不快，否则就会是更严重的事故 → would have been。</li><li>D ❌ had been 是过去完成时，主句的虚拟结果要用 would have been。</li></ul><p><strong>整句翻译</strong>：幸运的是，事故发生时他车开得不快；否则我敢肯定，那会成为一起更严重的事故。</p><p><strong>词组</strong>：<code>at the time of the accident</code> 事故发生时（提示过去）；<code>otherwise</code> 否则（承接事实，引出虚拟结果）</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件含蓄虚拟）：He came to town yesterday; otherwise/or I would not have met him.</p></details><p><strong>He did not regret saying what he did but felt that he ____ it differently. （他不后悔自己说过的话，但觉得本可以换一种方式表达。）</strong></p><ul><li>A. could express</li><li>B. would express</li><li>C. could have expressed</li><li>D. must have expressed</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（could have expressed）</strong> —— 表示过去本可以换一种方式表达却没有，用 could have expressed。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ could express 表现在或将来，与“已经说过的话”这件事的时间不符。</li><li>B ❌ would express 表过去将来，不表“本来可以”。</li><li>C ✅ 过去本来能够换一种方式表达却没有，用 could have expressed。</li><li>D ❌ must have expressed 是对过去的肯定推测“一定表达了”，与 felt 的遗憾语气相反。干扰点：把“本可以”与“一定是”混淆。</li></ul><p><strong>整句翻译</strong>：他不后悔自己说过的话，但觉得本可以换一种方式表达。</p><p><strong>词组</strong>：<code>regret doing sth.</code> 后悔做过某事；<code>in a different way</code> 用另一种方式</p><p><strong>对比自测</strong>：做完后对照 quiz:23，比较两题的判断依据</p><p><strong>原文定位</strong>（课件情态动词 + have done）：could have done：过去本有能力或机会做，实际没做</p></details><p><strong>I told your friend how to get to the hotel, but perhaps I ____ her there. （我告诉了你的朋友怎样去酒店，但也许我本应该开车送她过去。）</strong></p><ul><li>A. would have driven</li><li>B. must have driven</li><li>C. might have driven</li><li>D. should have driven</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（should have driven）</strong> —— 表示过去本应该开车送她却没有，用 should have driven。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ would have driven 表“在某种条件下本会开车送”，句中并没有条件，也不含“应该”的意味。</li><li>B ❌ must have driven 是“一定送过”的肯定推测，与 but perhaps 的转折、遗憾语气冲突。</li><li>C ❌ might have driven 是“也许送过”，仍然是推测，不是“本应该”。</li><li>D ✅ 过去本应该开车送她却没有，用 should have driven。</li></ul><p><strong>整句翻译</strong>：我告诉了你的朋友怎样去酒店，但也许我本应该开车送她过去。</p><p><strong>词组</strong>：<code>how to get to the hotel</code> 怎样去酒店（疑问词 + 不定式）；<code>drive sb. there</code> 开车送某人去那里</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件情态动词 + have done）：should have done：过去本应该做，实际没做</p></details><p><strong>【25 湖南】If I were you, I ____ for her opinion. （如果我是你，我会征求她的意见。）</strong></p><ul><li>A. asked</li><li>B. would ask</li><li>C. ask</li><li>D. will ask</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（would ask）</strong> —— If I were you 表现在虚拟，主句用 would ask。（真题在线）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ asked 是过去式；主句虚拟要用 would + 动词原形，不能用过去式。</li><li>B ✅ If I were you 表现在虚拟，主句用 would ask。（真题：25 湖南）</li><li>C ❌ ask 是一般现在时，与虚拟主句的形式不符。干扰点：把从句的过去形式误当成“主句也用真实时态”。</li><li>D ❌ will ask 是真实将来时，与 If I were you 的虚拟语气不搭。</li></ul><p><strong>整句翻译</strong>：如果我是你，我会征求她的意见。</p><p><strong>词组</strong>：<code>ask for one&#39;s opinion</code> 征求某人的意见；<code>If I were you</code> 如果我是你（现在虚拟）</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 if 虚拟）：If I were you, I would apply for the job.</p></details><p><strong>【22 重庆】An order came that all the army supply ____ to the front before daybreak. （命令传来：所有军需品必须在天亮前送往前线。）</strong></p><ul><li>A. be sent</li><li>B. should send</li><li>C. were went</li><li>D. have sent</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（be sent）</strong> —— order 后同位语从句用 (should) do；supply 与 send 为被动关系，用 (should) be sent。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ order 属“两个命令”，同位语从句用 (should) + 动词原形；supply 与 send 是被动关系 → (should) be sent。（真题：22 重庆）</li><li>B ❌ should send 是主动态，军需品不会自己送往前线。干扰点：只顾虚拟形式忘了语态。</li><li>C ❌ were went 语法不成立（went 是过去式，不能跟 were 连用），结构也不对。</li><li>D ❌ have sent 是主动的现在完成时，既没虚拟也丢了被动。</li></ul><p><strong>整句翻译</strong>：命令传来：所有军需品必须在天亮前送往前线。</p><p><strong>词组</strong>：<code>army supply</code> 军需品；<code>before daybreak</code> 天亮前</p><p><strong>对比自测</strong>：做完后对照 quiz:1，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 (should) be 型）：被动结构为 (should) be + 过去分词</p></details><p><strong>【24 重庆】If you had done your homework yesterday, you ____ how to answer the question now. （如果你昨天做了作业，现在就会知道怎样回答这个问题。）</strong></p><ul><li>A. know</li><li>B. knew</li><li>C. will know</li><li>D. would know</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（would know）</strong> —— 过去条件造成现在结果：had done / would know。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ know 是真实的一般现在时，主句仍是虚拟结构。</li><li>B ❌ knew 是过去式，主句虚拟要用 would + 动词原形，不能用过去式。</li><li>C ❌ will know 是真实将来时，与 now 的时间不符。</li><li>D ✅ 从句 yesterday（过去）用 had done，主句 now（现在）用 would know —— 错综时间虚拟。（真题：24 重庆）</li></ul><p><strong>整句翻译</strong>：如果你昨天做了作业，现在就会知道怎样回答这个问题。</p><p><strong>词组</strong>：<code>do one&#39;s homework</code> 做作业；<code>how to answer the question</code> 怎样回答这个问题</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件错综时间虚拟）：If you had left earlier, you would be at the concert now.</p></details><p><strong>【24 湖南】If you ____ him about the rainy weather, he ____ his umbrella. （如果你当时提醒过他会下雨，他就会带伞了。）</strong></p><ul><li>A. warn; would bring</li><li>B. had warned; would bring</li><li>C. warned; would have brought</li><li>D. had warned; would have brought</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（had warned; would have brought）</strong> —— 与过去事实相反：had warned / would have brought。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ warn 是现在的真实形式，主句 would bring 只对现在或将来虚拟。</li><li>B ❌ 从句 had warned 对了（过去），但主句 would bring 错——该用 would have brought。</li><li>C ❌ 从句 warned 只能对现在虚拟，主句 would have brought 是过去虚拟的结果，两半时间对不上。</li><li>D ✅ 与过去事实相反：从句 had warned，主句 would have brought。（真题：24 湖南）</li></ul><p><strong>整句翻译</strong>：如果你当时提醒过他会下雨，他就会带伞了。</p><p><strong>词组</strong>：<code>warn sb. about sth.</code> 提醒某人注意某事；<code>the rainy weather</code> 下雨的天气</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件与过去事实相反）：You would not have caught a cold if you had put on more clothes.</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 should 型标志词：<strong>一坚持、二命令、四建议、四要求。</strong></p><p>were 型时间后退：<strong>现在过去式，过去 had done，将来 would/could do。</strong></p><p>if 三时空：<strong>现过将来分别看，从句 did/had done/did-were to-should，主句 would do/have done。</strong></p><p>if 倒装：<strong>were、should、had 才能提，省 if 后放句首。</strong></p><p>错综时间：<strong>各看各的时间，各用各的虚拟。</strong></p></div><p>延伸阅读：虚拟语气 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,202),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/14/`},{default:i(()=>[...l[5]||=[e(`← 第 14 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/16/`},{default:i(()=>[...l[7]||=[e(`第 16 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};